import { Button } from "../components/button";

import { EffectModel } from "./effect-model";

import type { Component, Setter } from "solid-js";

export interface EffectExampleProps {
	action: (valueSetter: Setter<string>) => void;
	name: string;
}

export const EffectComponent: Component<EffectExampleProps> = (props) => {
	return (
		<Button
			class="text-base mx-2 mt-2"
			onActivate={() => props.action(EffectModel.setValue)}
		>
			{props.name}&nbsp;Effect
		</Button>
	);
};
